def _dims(t, out):
    """Drop size-1 dims; return innermost-first (size, in_stride, out_stride)."""
    keep = []
    for d in range(t.dim()):
        s = int(t.shape[d])
        if s == 1:
            continue
        keep.append((s, int(t.stride(d)), int(out.stride(d))))
    if not keep:
        keep = [(1, 0, 0)]
    keep.reverse()
    return keep


