def _batched_launch(tensors, outs, other, numels):
    """One launch for the whole list: each program resolves its slot from
    host-computed cumulative tile bounds."""
    live = [i for i, n in enumerate(numels) if n > 0]
    block = _batched_block(
        tensors[live[0]].dtype,
        min(numels[i] for i in live),
        max(numels[i] for i in live),
    )
    slots = 4 if len(live) <= 4 else _MAX_SLOTS
    in_ptrs = []
    out_ptrs = []
    ns = []
    bounds = []
    total = 0
    for slot in range(slots):
        if slot < len(live):
            i = live[slot]
            in_ptrs.append(tensors[i])
            out_ptrs.append(outs[i])
            ns.append(numels[i])
            total += triton.cdiv(numels[i], block)
        else:
            in_ptrs.append(tensors[live[0]])
            out_ptrs.append(outs[live[0]])
            ns.append(0)
        bounds.append(total)
    args = []
    for k in range(slots):
        args.append(in_ptrs[k])
        args.append(out_ptrs[k])
    wide = tensors[live[0]].element_size() == 8
    even = all(numels[i] % block == 0 for i in live)
    bounds = bounds[: slots - 1]
    if slots == 4 and even:
        _mul_batched4_even_kernel[(total,)](
            *args, other, *bounds, BLOCK=block, WIDE=wide
        )
        return
    args.append(other)
    args.extend(ns)
    args.extend(bounds)
    kernel = _mul_batched4_kernel if slots == 4 else _mul_batched_kernel
    kernel[(total,)](*args, BLOCK=block, WIDE=wide, EVEN=even)


def foreach_mul_tensor(self, other):
    tensors = self if isinstance(self, (list, tuple)) else [self]
    outs = [torch.empty_like(t) for t in tensors]
    if not tensors:
        return outs
    numels = [t.numel() for t in tensors]
    if not isinstance(other, torch.Tensor):
        for t, out, numel in zip(tensors, outs, numels):
            if numel:
                _flat_launch_scalar(t, out, other, numel)
        return outs
    live = [i for i, n in enumerate(numels) if n > 0]
    if not live:
        return outs
    dtypes = {tensors[i].dtype for i in live}
    if (
        len(live) <= _MAX_SLOTS
        and len(dtypes) == 1
        and all(tensors[i].is_contiguous() for i in live)
        and all(outs[i].is_contiguous() for i in live)
    ):
        _batched_launch(tensors, outs, other, numels)
    else:
        for t, out, numel in zip(tensors, outs, numels):
            if not numel:
                continue
            if t.is_contiguous():
                _flat_launch(t, out, other, numel)
            else:
                _strided_launch(t, out, other, numel)
    return outs
